#pragma once
#include "binary.hpp"
#include <set>
namespace worlded {
namespace reference_codec {
inline void put(Bytes& out,std::uint32_t n){for(unsigned i=0;i<4;i++)out.push_back(n>>(8*i));}
inline void blob(Bytes& out,const Bytes& bytes){if(bytes.size()>resource_limit)throw std::runtime_error("Reference blob exceeds limit");put(out,unsigned(bytes.size()));out.insert(out.end(),bytes.begin(),bytes.end());}
inline void text(Bytes& out,const std::string& value){blob(out,Bytes(value.begin(),value.end()));}
inline Bytes blob(BinaryReader& in){auto size=in.u32();if(size>resource_limit)throw std::runtime_error("Reference blob exceeds limit");return in.bytes(size);}
inline std::string text(BinaryReader& in){auto bytes=blob(in);return std::string(bytes.begin(),bytes.end());}
inline void magic(BinaryReader& in,const char* expected){auto bytes=in.bytes(8);if(std::string(bytes.begin(),bytes.end())!=std::string(expected,8))throw std::runtime_error("Unsupported WorldED reference format");}
}
Bytes encode_scene_reference(const SceneReference& ref){using namespace reference_codec;Bytes out={'W','E','R','E','F','0','1',0};text(out,ref.id);text(out,ref.map);text(out,ref.source_path);text(out,ref.source_hash);put(out,std::uint32_t(ref.sector));put(out,std::uint32_t(ref.sector>>32));put(out,ref.generated);blob(out,ref.ground);put(out,unsigned(ref.origins.size()));for(const auto& origin:ref.origins){text(out,origin.editor_id);text(out,origin.source_path);text(out,origin.source_hash);put(out,origin.ordinal);put(out,origin.mobile);blob(out,encode_instance(origin.object));}put(out,unsigned(ref.resources.size()));for(const auto& [path,bytes]:ref.resources){text(out,path);blob(out,bytes);}return out;}
std::shared_ptr<SceneReference> decode_scene_reference(const Bytes& bytes){using namespace reference_codec;BinaryReader in(bytes);magic(in,"WEREF01\0");auto ref=std::make_shared<SceneReference>();ref->id=text(in);ref->map=text(in);ref->source_path=text(in);ref->source_hash=text(in);auto lo=in.u32(),hi=in.u32();ref->sector=std::uint64_t(lo)|(std::uint64_t(hi)<<32);ref->generated=in.u32()!=0;ref->ground=blob(in);Sector validate(ref->ground);auto count=in.u32();if(count>100000)throw std::runtime_error("Too many reference objects");std::set<std::string> keys;for(unsigned i=0;i<count;i++){SceneOrigin origin;origin.editor_id=text(in);if(origin.editor_id.empty() || !keys.insert(origin.editor_id).second)throw std::runtime_error("Duplicate reference authoring identity");origin.source_path=text(in);origin.source_hash=text(in);origin.ordinal=in.u32();origin.mobile=in.u32()!=0;auto objects=read_objects(blob(in));if(objects.size()!=1)throw std::runtime_error("Invalid reference object");origin.object=std::move(objects[0]);origin.object.editor_id=origin.editor_id;ref->origins.push_back(std::move(origin));}count=in.u32();if(count>16384)throw std::runtime_error("Too many reference resources");for(unsigned i=0;i<count;i++){auto path=text(in);if(!ref->resources.emplace(path,blob(in)).second)throw std::runtime_error("Duplicate reference resource");}if(in.pos!=in.end)throw std::runtime_error("Trailing reference bytes");return ref;}
Bytes encode_scene_selections(const std::vector<GameObject>& objects){using namespace reference_codec;Bytes out={'W','E','S','E','L','0','1',0};put(out,unsigned(objects.size()));for(const auto& object:objects){text(out,object.editor_id.empty()?object.id:object.editor_id);blob(out,encode_instance(object));}return out;}
void restore_scene_selections(std::vector<GameObject>& objects,const Bytes& bytes){using namespace reference_codec;BinaryReader in(bytes);magic(in,"WESEL01\0");auto count=in.u32();if(count!=objects.size())throw std::runtime_error("Project selections do not match exported objects");std::map<Bytes,std::vector<std::string>> ids;for(unsigned i=0;i<count;i++){auto key=text(in);auto object=blob(in);ids[object].push_back(key);}if(in.pos!=in.end)throw std::runtime_error("Trailing selection bytes");for(auto& object:objects){auto it=ids.find(encode_instance(object));if(it==ids.end() || it->second.empty())throw std::runtime_error("Exported object changed outside WorldED; selection provenance cannot be restored");object.editor_id=it->second.front();it->second.erase(it->second.begin());}}
}
